CREATE TABLE IF NOT EXISTS fleet_vehicle (id CHAR(36) PRIMARY KEY, registration VARCHAR(20) NOT NULL, make_model VARCHAR(120) NOT NULL, kind VARCHAR(16) NOT NULL, seats SMALLINT NOT NULL, status VARCHAR(16) NOT NULL, note VARCHAR(300) NOT NULL DEFAULT '', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY fleet_vehicle_registration_unique (registration)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fleet_driver (person_id CHAR(36) PRIMARY KEY, phone VARCHAR(32) NOT NULL DEFAULT '', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT fleet_driver_person_fk FOREIGN KEY (person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fleet_request_sequence (fiscal_year INT PRIMARY KEY, last_value INT NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fleet_trip (id CHAR(36) PRIMARY KEY, vehicle_id CHAR(36) NOT NULL, driver_person_id CHAR(36) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status VARCHAR(16) NOT NULL, odometer_out INT NULL, odometer_in INT NULL, departed_at DATETIME NULL, returned_at DATETIME NULL, created_by_person_id CHAR(36) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY fleet_trip_vehicle_index (vehicle_id, starts_at), KEY fleet_trip_driver_index (driver_person_id, starts_at), CONSTRAINT fleet_trip_vehicle_fk FOREIGN KEY (vehicle_id) REFERENCES fleet_vehicle(id), CONSTRAINT fleet_trip_driver_fk FOREIGN KEY (driver_person_id) REFERENCES fleet_driver(person_id), CONSTRAINT fleet_trip_creator_fk FOREIGN KEY (created_by_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fleet_request (id CHAR(36) PRIMARY KEY, reference VARCHAR(32) NOT NULL, requester_person_id CHAR(36) NOT NULL, organization_id CHAR(36) NOT NULL, request_id CHAR(36) NULL, official_travel_id CHAR(36) NULL, purpose VARCHAR(300) NOT NULL, destination VARCHAR(300) NOT NULL, province VARCHAR(100) NOT NULL, depart_at DATETIME NOT NULL, return_at DATETIME NOT NULL, passenger_count SMALLINT NOT NULL, passenger_names VARCHAR(1000) NOT NULL DEFAULT '', contact_phone VARCHAR(32) NOT NULL DEFAULT '', dispatch_status VARCHAR(16) NOT NULL, trip_id CHAR(36) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY fleet_request_reference_unique (reference), UNIQUE KEY fleet_request_request_unique (request_id), KEY fleet_request_requester_index (requester_person_id), KEY fleet_request_travel_index (official_travel_id), KEY fleet_request_trip_index (trip_id), KEY fleet_request_dispatch_index (dispatch_status, depart_at), CONSTRAINT fleet_request_requester_fk FOREIGN KEY (requester_person_id) REFERENCES person(id), CONSTRAINT fleet_request_organization_fk FOREIGN KEY (organization_id) REFERENCES organization(id), CONSTRAINT fleet_request_request_fk FOREIGN KEY (request_id) REFERENCES request(id), CONSTRAINT fleet_request_travel_fk FOREIGN KEY (official_travel_id) REFERENCES official_travel(id), CONSTRAINT fleet_request_trip_fk FOREIGN KEY (trip_id) REFERENCES fleet_trip(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fleet_request_history (id CHAR(36) PRIMARY KEY, fleet_request_id CHAR(36) NOT NULL, action VARCHAR(64) NOT NULL, actor_person_id CHAR(36) NOT NULL, reason VARCHAR(500) NULL, created_at DATETIME NOT NULL, KEY fleet_request_history_request_index (fleet_request_id, created_at), CONSTRAINT fleet_request_history_request_fk FOREIGN KEY (fleet_request_id) REFERENCES fleet_request(id), CONSTRAINT fleet_request_history_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
